export function RoomPanel(
rooms: Room[], selectedId: string, onSelect: (id: string) => void) {
  const { available, booked, availableSeats, bookedSeats } = rooms.reduce(
    (acc, { id, name, capacity, floor }) => {
      acc[id] = {
        name,
        capacity,
        seats: capacity - (bookedSeats[id] || 0),
        free: availableSeats[id] || 0,
        freeSeats: bookedSeats[id] || 0,
        availability: booked[id] || 0,
      }
      return acc
    },
    {} as { [key: string]: RoomAvailability }
  )
  return (
    <div className="w-full flex flex-col">
      <RoomPanelHeader {...{ selectedId, onSelect }} />
      <RoomPanelBody rooms={rooms} available={available} booked={booked} />
    </div>
  )
}

